use xiom.io;
type BudgetTracker = {
  balance: Int;
  total_spent: Int;
}

fn add_expense(tracker: &mut BudgetTracker, amount: Int) {
  tracker.balance -= amount;
  tracker.total_spent += amount;
}

fn add_income(tracker: &mut BudgetTracker, amount: Int) {
  tracker.balance += amount;
}

fn print_summary(tracker: &BudgetTracker) {
  io.println(tracker.balance.to_str());
  io.println(tracker.total_spent.to_str());
}

fn main() -> Int {
  var tracker = BudgetTracker{ balance: 0, total_spent: 0 };
  add_income(&mut tracker, 1000);
  add_expense(&mut tracker, 250);
  add_expense(&mut tracker, 100);
  print_summary(&tracker);
  return 0;
}
